#!/usr/bin/env bash
# PreToolUse(Edit|Write): asks the person before an edit that AGENTS.md reserves to a generator or to
# their judgement (Boundaries), and stays silent otherwise:
#   src/Infrastructure/<name>.Persistence/Migrations/**   generated by dotnet-ef, never hand-edited
#   docs/api/openapi.v1.json                              the OpenAPI snapshot, regenerated by a test
#   a Write that creates a *.csproj                       a new project (ask first)
#   an edit that adds a package to Directory.Packages.props or a *.csproj   (ask first)
#   an edit that adds a <Project> to a *.slnx             a new project (ask first)
# A version bump, a project moved between solution folders and every other file pass without a
# prompt. The reason names the command that does the job instead, and the person may still allow the
# edit (a data migration, say). Only paths inside the project, or inside the git checkout Claude works
# in (the input's cwd: a worktree, say), count. The path is normalised first (src/../, //, /./), and the
# two path rules match at any depth below that folder, so a worktree's copy under .claude/worktrees/
# asks too, while a Migrations folder outside a Persistence project is ordinary code.
# scripts/check-hooks.sh has a case for every decision.
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" 2>/dev/null && pwd)" || exit 0
# shellcheck source=common.sh
. "$here/common.sh" 2>/dev/null || exit 0

read_input || exit 0
project_root || exit 0
work_root
tool="$(json_string tool_name)"
path="$(json_string file_path)"
[ -n "$path" ] || exit 0
relative_path "$path"
rel="$REL"
case "$rel" in
  '' | /* | [A-Za-z]:/* | .. | ../*) exit 0 ;;   # outside the project and the checkout
esac
file="${REL_ROOT:-$PROJECT_DIR}/$rel"

migrations='/(src/Infrastructure/[^/]+\.Persistence)/Migrations/'
if [[ "/$rel" =~ $migrations ]]; then
  project="${BASH_REMATCH[1]}"
  decide ask "$rel is a generated migration: migrations are generated, never hand-edited (AGENTS.md, .claude/rules/persistence.md). To change one that is not applied anywhere yet, remove it and generate it again: ./scripts/ef.sh migrations remove --force --project $project, change the model, then ./scripts/ef.sh migrations add <Name> --project $project (the add-migration skill). A data migration (SQL the model cannot express) is the one reason to edit by hand."
fi

case "/$rel" in
  */docs/api/openapi.v1.json)
    decide ask "$rel is the snapshot of the OpenAPI document the API serves (ADR-0025), regenerated rather than edited: UPDATE_OPENAPI_SNAPSHOT=1 ./scripts/dotnet.sh test tests/Trellis.ApiTests writes it from the running code, and OpenApiSnapshotTests fails while the file and the code disagree. Change the endpoint or the contract instead." ;;
esac

# The text before and after the change: the replaced and the replacing string of an Edit; the file on
# disk (empty when it does not exist yet) and the new content of a Write.
before_after() {
  if [ "$tool" = Write ]; then
    before="$(cat "$file" 2>/dev/null)" || before=""
    after="$(json_string content)"
  else
    before="$(json_string old_string)"
    after="$(json_string new_string)"
  fi
}

# Include may follow other attributes and have blanks around its =; the element may span lines.
package='<(Global)?Package(Reference|Version)[[:space:]]([^>]*[[:space:]])?Include[[:space:]]*='
case "$rel" in
  *.csproj | Directory.Packages.props | */Directory.Packages.props)
    case "$rel" in
      *.csproj)
        if [ "$tool" = Write ] && [ ! -e "$file" ]; then
          decide ask "$rel is a new project, and adding a project is an ask-first change (AGENTS.md, Boundaries). If it is agreed: add it to the .slnx, give it its place in the dependency flow, and anchor it in tests/Trellis.ArchitectureTests/ArchitectureRules.cs so the layer tests cover it (the architecture-guard reviewer checks this)."
        fi ;;
    esac
    before_after
    if [ "$(count_in "$package" "$after")" -gt "$(count_in "$package" "$before")" ]; then
      decide ask "This edit adds a NuGet package to $rel, and adding a package is an ask-first change (AGENTS.md, Boundaries). Check the LICENSE CEILINGS block in Directory.Packages.props (ADR-0011) and that a package family moves in one Dependabot group (ADR-0029). A version change alone does not ask."
    fi ;;
  *.slnx)
    before_after
    if [ "$(count_in '<Project[[:space:]]+Path=' "$after")" -gt "$(count_in '<Project[[:space:]]+Path=' "$before")" ]; then
      decide ask "This edit adds a project to $rel, and adding a project is an ask-first change (AGENTS.md, Boundaries). If it is agreed, anchor it in tests/Trellis.ArchitectureTests/ArchitectureRules.cs so the layer tests cover it. Moving a project between solution folders does not ask."
    fi ;;
esac
exit 0
